<pre class="xfBb-code" data-lang="php">function delete_dir($dir, $subfolders = false)
{
    if (substr($dir, strlen($dir)-1, 1) == &#039;/&#039;) $dir = substr($dir, 0, strlen($dir)-1);
    if ($dir == &#039;/&#039;) $dir = BB_ROOT;

    if ($content = opendir($dir))
    {
        while ($object = readdir($content))
        {
            // Исключения
            if ($object != &#039;index.php&#039; &amp;&amp; $object != &#039;index.html&#039; &amp;&amp; $object != &#039;.htaccess&#039; &amp;&amp; $object != &#039;.&#039; &amp;&amp; $object != &#039;..&#039; &amp;&amp; !is_link(&quot;$dir/$object&quot;))
            {
                if (is_file(&quot;$dir/$object&quot;))
                {
                    unlink(&quot;$dir/$object&quot;);
                }

                if ($subfolders &amp;&amp; is_dir(&quot;$dir/$object&quot;)) delete_dir(&quot;$dir/$object&quot;);
            }
        }
    }
    closedir($content);
}</pre> <br />
